// DawnBreaker GM compatibility adapter. Upstream LinkSwift is kept unmodified.
(()=>{if(window.__dawnLinkSwift)return;window.__dawnLinkSwift=true;const bridge=window.dawnCloud||{request:options=>new Promise((resolve,reject)=>{const id=crypto.randomUUID();window.__dawnCloudCallbacks[id]={resolve,reject};DawnCloud.request(id,JSON.stringify(options));}),clipboard:text=>DawnCloud.clipboard(text),open:url=>DawnCloud.open(url),download:options=>DawnCloud.download(JSON.stringify(options))};window.__dawnCloudCallbacks={};window.__dawnCloudReply=(id,error,value)=>{const cb=window.__dawnCloudCallbacks[id];if(!cb)return;delete window.__dawnCloudCallbacks[id];error?cb.reject(Error(error)):cb.resolve(value);};
window.unsafeWindow=window;window.GM_info={script:{name:'LinkSwift',version:'1.1.3',author:'Hmjz100、油小猴'},scriptHandler:'DawnBreaker'};window.GM_getValue=(key,otherwise)=>{try{const v=localStorage.getItem('dawn:gm:'+key);return v===null?otherwise:JSON.parse(v);}catch{return otherwise;}};window.GM_setValue=(key,value)=>localStorage.setItem('dawn:gm:'+key,JSON.stringify(value));window.GM_deleteValue=key=>localStorage.removeItem('dawn:gm:'+key);window.GM_setClipboard=text=>bridge.clipboard(String(text));window.GM_openInTab=url=>{bridge.open(String(url));return{close(){}};};window.GM_getResourceText=name=>(window.__dawnCloudResources||{})[name]||'';window.GM_registerMenuCommand=(name,callback)=>{const mount=()=>{let box=document.getElementById('dawn-cloud-commands');if(!box){box=document.createElement('details');box.id='dawn-cloud-commands';box.style.cssText='position:fixed;bottom:14px;left:14px;z-index:2147483647;background:#fff;color:#222;padding:10px;border:1px solid #ddd;border-radius:8px;font:14px sans-serif';box.innerHTML='<summary>破晓 · 网盘助手</summary>';document.body.append(box);}const b=document.createElement('button');b.textContent=name;b.onclick=callback;b.style.cssText='display:block;margin:8px 0;background:white;color:#222;border:1px solid #ddd;padding:8px';box.append(b);};document.body?mount():document.addEventListener('DOMContentLoaded',mount,{once:true});};
window.GM_xmlhttpRequest=details=>{let cancelled=false;const promise=bridge.request({url:String(details.url),method:details.method||'GET',headers:details.headers||{},data:typeof details.data==='string'?details.data:undefined,responseType:details.responseType||'text',timeout:Math.min(details.timeout||30000,120000)});promise.then(value=>{if(cancelled)return;if(value.base64){const raw=atob(value.base64),bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));value.response=details.responseType==='blob'?new Blob([bytes]):bytes.buffer;}else{value.response=details.responseType==='json'?JSON.parse(value.responseText||'null'):value.responseText;}details.onload?.(value);details.onloadend?.(value);},error=>{if(cancelled)return;details.onerror?.({error:String(error),status:0});details.onloadend?.({status:0});});return{abort(){cancelled=true;details.onabort?.({status:0});}};};
window.GM_registerMenuCommand('粘贴已解析直链并下载',()=>{
 let existing=document.getElementById('dawn-direct-download');if(existing){existing.showModal();return;}
 const dialog=document.createElement('dialog');dialog.id='dawn-direct-download';dialog.style.cssText='width:min(500px,calc(100vw - 48px));box-sizing:border-box;border:1px solid #ccc;border-radius:12px;padding:24px;background:#fff;color:#20251e;font:14px/1.6 system-ui;z-index:2147483647';
 dialog.innerHTML='<form><h2 style="font:600 20px system-ui;margin:0 0 12px">下载已解析的文件</h2><p>先选择文件并使用 LinkSwift 解析，再复制 HTTPS 下载直链。网盘首页或分享页面地址不能在此下载。</p><label style="display:block">HTTPS 直链<textarea name="url" required rows="4" style="display:block;width:100%;box-sizing:border-box;margin:8px 0;padding:8px" placeholder="https://…"></textarea></label><label style="display:block">来源页面（选填）<input name="referer" type="url" style="display:block;width:100%;box-sizing:border-box;padding:8px" placeholder="https://…"></label><p role="status" aria-live="polite"></p><div style="display:flex;gap:12px;justify-content:flex-end"><button type="button" data-close style="padding:8px 16px">关闭</button><button type="submit" style="padding:8px 16px">开始下载</button></div></form>';
 const form=dialog.querySelector('form'),status=dialog.querySelector('[role=status]'),submit=dialog.querySelector('[type=submit]');dialog.querySelector('[data-close]').onclick=()=>dialog.close();
 form.onsubmit=async event=>{event.preventDefault();submit.disabled=true;status.textContent='正在提交下载…';try{const values=new FormData(form),url=new URL(String(values.get('url')).trim()),referer=String(values.get('referer')||'').trim();if(url.protocol!=='https:'||url.username||url.password)throw Error('请填写已解析的 HTTPS 下载直链');const result=await bridge.download({url:url.href,headers:referer?{Referer:referer}:{}});status.textContent=result?.message||'已提交下载。请查看保存窗口或系统下载通知。';status.style.color='#235840';}catch(error){status.textContent=String(error.message||error);status.style.color='#a22';}finally{submit.disabled=false;}};document.body.append(dialog);dialog.showModal();
});})();
